}

import { useReducedMotion } from "motion/react";
import { LazyMotion, domAnimation, m } from "motion/react";

export type PainFreeTreatmentProps = {
  eyebrow: string;
  title: string;
  image: { src: string; alt: string };
  phone: string;
  phoneLabel: string;
};

export default function PainFreeTreatment({
  eyebrow,
  title,
  image,
  phone,
  phoneLabel,
}: PainFreeTreatmentProps) {
  const prefersReducedMotion = useReducedMotion();

  const motionProps = prefersReducedMotion
    ? { className: "relative aspect-[4/3] w-full overflow-hidden md:aspect-auto md:min-h-[480px]" }
    : {
        initial: { opacity: 0, y: 24 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, margin: "-80px" },
        transition: { duration: 0.6, ease: "easeOut" },
        className: "relative aspect-[4/3] w-full overflow-hidden md:aspect-auto md:min-h-[480px]",
      };

  const textMotionProps = prefersReducedMotion
    ? { className: "flex flex-col justify-center px-gutter py-14 md:py-section md:pl-12 lg:pl-16" }
    : {
        initial: { opacity: 0, y: 24 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, margin: "-80px" },
        transition: { duration: 0.6, ease: "easeOut" },
        className: "flex flex-col justify-center px-gutter py-14 md:py-section md:pl-12 lg:pl-16",
      };

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page grid-cols-1 gap-0 md:grid-cols-2">
          <m.div {...motionProps}>
            <img
              src={image.src}
              alt={image.alt}
              className="h-full w-full object-cover"
              loading="lazy"
            />
          </m.div>

          <m.div {...textMotionProps}>
            <span className="text-small font-bold uppercase tracking-wide text-muted-foreground">
              {eyebrow}
            </span>
            <h2 className="mt-3 max-w-text font-display text-h2 font-bold text-balance wrap-break-word">
              {title}
            </h2>
            <a
              href={phone}
              className="mt-8 inline-flex min-h-11 w-fit items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              {phoneLabel}
            </a>
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

